class StoreSaleRequest extends FormRequest {public function authorize():bool{return $this->user()->hasPermission('sales.create');}public function rules():array{return ['customer_profile_id'=>['nullable','ulid','exists:customer_profiles,id'],'sales_order_id'=>['nullable','ulid','exists:sales_orders,id'],'price_list_id'=>['required','ulid','exists:price_lists,id'],'sold_at'=>['required','date'],'due_at'=>['nullable','date','after_or_equal:sold_at'],'discount'=>['required','integer','min:0'],'lines'=>['required','array','min:1'],'lines.*.sales_order_line_id'=>['nullable','ulid','exists:sales_order_lines,id'],'lines.*.presentation_id'=>['required','ulid','distinct','exists:product_presentations,id'],'lines.*.quantity'=>['required','numeric','gt:0','decimal:0,6'],'lines.*.unit_price'=>['nullable','integer','min:0'],'lines.*.discount'=>['required','integer','min:0'],'lines.*.price_reason'=>['nullable','string','max:1000'],'payments'=>['sometimes','array'],'payments.*.financial_account_id'=>['required','ulid','exists:financial_accounts,id'],'payments.*.amount'=>['required','integer','gt:0'],'payments.*.reference'=>['nullable','string','max:255']];}}
